  $stmgjson${"slug": "strategic-management", "title": "Strategic Management", "description": "Students learn strategy as disciplined choice: what the organization exists to do, where it will compete, how it will win, and what it will refuse to do. The course covers industry structure, positioning, resources, corporate scope, growth, global and nonmarket strategy, innovation, uncertainty, governance, implementation, and a board-ready recommendation.", "topics": [{"id": "f4a94b15-503f-46c0-8ac4-98840ca21bab", "type": "topic", "title": "Strategic Thinking, Purpose, and Strategic Intent", "description": "Students learn strategy as disciplined choice: what the organization exists to do, where it will compete, how it will win, and what it will refuse to do.", "children": [{"id": "31a7e27b-f40d-4590-9d81-c27f00f4d0db", "type": "subtopic", "title": "Strategy as choice", "children": [{"id": "d5606fcc-dfb7-4178-8090-25dabce834a5", "type": "concept", "title": "Where to compete and how to win"}, {"id": "11009869-c33a-4a4d-bf9d-ce398f4ec5ff", "type": "concept", "title": "Tradeoffs, fit, and coherence"}, {"id": "045c3aaf-46b8-4094-a71a-bebc0fb7d875", "type": "concept", "title": "Strategy versus goals, tactics, plans, and operational effectiveness"}], "description": "The gist is that strategy is not a wish list; it is a set of integrated choices under constraints."}, {"id": "a707eefe-9b7b-4bb8-9013-caefe8c02807", "type": "subtopic", "title": "Mission, vision, values, and intent", "children": [{"id": "557ba6ee-3de3-4c5b-abc6-aece7d6e0b54", "type": "concept", "title": "Mission and scope"}, {"id": "3ca32dad-b940-4fab-9d61-3caddd88a81e", "type": "concept", "title": "Vision and ambition"}, {"id": "1b83989e-c707-4367-a995-3f0463599654", "type": "concept", "title": "Strategic intent and stretch goals"}], "description": "Purpose statements matter when they discipline priorities and resource allocation."}, {"id": "c43c722a-4f05-464a-a52c-0530515a699e", "type": "subtopic", "title": "Strategic management process", "children": [{"id": "4ec2d23a-8e01-4542-b870-54a04739042c", "type": "concept", "title": "Analysis, formulation, implementation, and evaluation"}, {"id": "1797d260-15a3-48ca-9fc5-37ca8d5b64e0", "type": "concept", "title": "Strategic planning versus emergent strategy"}, {"id": "c3c50e9e-dffa-42a8-8eaf-7a3a428e7191", "type": "concept", "title": "Case method and evidence-based argument"}], "description": "Students learn strategy as an iterative cycle of diagnosis, choice, execution, and learning."}]}, {"id": "d1190614-e6b4-45de-90e1-80276cc35778", "type": "topic", "title": "External Environment and Industry Structure", "description": "This topic develops the ability to read industry forces, macro trends, customers, complements, substitutes, and profit pools before choosing a position.", "children": [{"id": "cbdfa151-198a-40b0-8d24-9e800af15586", "type": "subtopic", "title": "Macro-environment analysis", "children": [{"id": "48372313-a24c-4f15-bb52-2cc534fd2883", "type": "concept", "title": "Political, economic, social, technological, environmental, and legal forces"}, {"id": "1b96e0eb-298f-481e-8e7b-336b328d7db5", "type": "concept", "title": "Signals, trends, shocks, and structural change"}, {"id": "3e7a7379-9ca9-4750-8b10-156ad1d2872a", "type": "concept", "title": "Implications for opportunity and threat"}], "description": "PESTEL analysis helps students identify external forces that can reshape markets."}, {"id": "87ca64e4-ec43-4407-afb9-6cb5b0a935b1", "type": "subtopic", "title": "Industry structure", "children": [{"id": "178605be-f562-4c6e-807e-1a93232294b6", "type": "concept", "title": "Porter's Five Forces"}, {"id": "aa8875f0-0976-49b0-aeab-f965c44cb1da", "type": "concept", "title": "Entry barriers, supplier power, buyer power, substitutes, and rivalry"}, {"id": "afe6f895-e3df-4d05-a13b-b0dbb15c9d75", "type": "concept", "title": "Profit pools and industry evolution"}], "description": "Students learn why some industries are more profitable than others."}, {"id": "ec8118b3-e0ef-4f20-b10d-ffb8b793c4a4", "type": "subtopic", "title": "Market and competitor analysis", "children": [{"id": "67891860-a2bf-4577-a0bd-be4599db339f", "type": "concept", "title": "Segments, jobs-to-be-done, willingness to pay, and switching costs"}, {"id": "81b92a45-635c-4266-b21d-50084f86b9a8", "type": "concept", "title": "Strategic groups and competitor positioning"}, {"id": "9460dcad-7dde-4698-bde8-9e7e7c20f1a2", "type": "concept", "title": "Complements, substitutes, and ecosystem roles"}], "description": "Good strategy requires understanding customers and rivals with specificity."}]}, {"id": "2704f91f-5442-451e-bedb-ba05c80cfba6", "type": "topic", "title": "Competitive Positioning and Business-Level Strategy", "description": "Students learn how firms create advantage through cost leadership, differentiation, focus, tradeoffs, and coherent activity systems.", "children": [{"id": "3151c5a1-6328-43eb-a764-45cb26623bf1", "type": "subtopic", "title": "Generic strategies", "children": [{"id": "ed630d0b-ffce-4d82-a6e4-f4c9b43dbf51", "type": "concept", "title": "Cost leadership"}, {"id": "b5876da9-43c9-4606-bb59-407cf6c5a566", "type": "concept", "title": "Differentiation"}, {"id": "4ffa470f-245d-45e1-9e26-cfbb77662873", "type": "concept", "title": "Focus and niche strategies"}], "description": "Students learn the classic routes to advantage and why being stuck in the middle is dangerous."}, {"id": "dab08a72-c946-48a3-806d-a85efecb7c77", "type": "subtopic", "title": "Activity systems and fit", "children": [{"id": "5481f062-c911-4e82-bd90-a807416be6f7", "type": "concept", "title": "Activity maps"}, {"id": "3439aa73-cd0a-4bc2-a117-1820349521b3", "type": "concept", "title": "Tradeoffs and strategic consistency"}, {"id": "98f1bd4e-f4a9-4659-b558-e1416d17f356", "type": "concept", "title": "Operational effectiveness versus strategic positioning"}], "description": "A strategy becomes durable when activities reinforce one another."}, {"id": "767cedb5-9b0a-434d-ac8f-bbf20a9e1149", "type": "subtopic", "title": "Customer value and willingness to pay", "children": [{"id": "b5c7990d-ab64-4441-b382-2c071bb11861", "type": "concept", "title": "Value proposition and value curve"}, {"id": "0b818ae8-78b4-429d-a821-3f83cf7744c8", "type": "concept", "title": "Price, cost, margin, and value capture"}, {"id": "2e7b4f29-1192-4672-8a69-c94fce4161af", "type": "concept", "title": "Blue ocean and value innovation"}], "description": "Strategy must connect economics to customer value."}]}, {"id": "2733d8a6-1c2e-4e84-849c-bb79b0390a81", "type": "topic", "title": "Internal Analysis, Resources, Capabilities, and Value Chain", "description": "This topic explains why some firms outperform others even inside the same industry by building resources, capabilities, routines, and activity systems competitors struggle to copy.", "children": [{"id": "df562194-a0c1-4cc6-baca-2a9261621fae", "type": "subtopic", "title": "Resource-based view", "children": [{"id": "44761ea9-f019-496c-848c-bef270cd3028", "type": "concept", "title": "VRIO: value, rarity, imitability, organization"}, {"id": "367721d9-e90d-4d15-b1ca-ce77a2dc2620", "type": "concept", "title": "Tangible, intangible, and human resources"}, {"id": "69e2cf0c-2949-47a5-8182-c0caba23254b", "type": "concept", "title": "Dynamic capabilities and learning"}], "description": "Students learn how firm-specific assets become sources of advantage."}, {"id": "5beb089a-bd0e-4500-bb1d-1ef4392061e4", "type": "subtopic", "title": "Value chain analysis", "children": [{"id": "b622aa5a-4ce7-4da7-8e1c-c598a63c1313", "type": "concept", "title": "Primary and support activities"}, {"id": "a46065b3-a67c-4949-9abd-1930e403fd7c", "type": "concept", "title": "Cost drivers and differentiation drivers"}, {"id": "0d1afac6-15bf-447e-ac18-0529e68945c7", "type": "concept", "title": "Linkages, outsourcing, and activity redesign"}], "description": "The value chain shows where advantage is created or lost across activities."}, {"id": "8c4f63a1-e13a-45ca-a9c7-872cc7a5a679", "type": "subtopic", "title": "Capabilities and routines", "children": [{"id": "a5590363-95a2-4257-900c-da8b75f9b51c", "type": "concept", "title": "Core competencies"}, {"id": "6ff9fb24-c8e8-498a-a68a-d2302968ad0f", "type": "concept", "title": "Path dependence and causal ambiguity"}, {"id": "5cdf6c85-6af3-483b-8107-288c47694658", "type": "concept", "title": "Capability gaps and capability building"}], "description": "Capabilities are built through repeated practice, coordination, and managerial systems."}]}, {"id": "7006c5e1-7231-4e5a-a0a8-82fcec3c773d", "type": "topic", "title": "SWOT, Strategic Issue Diagnosis, and Option Generation", "description": "Students learn to turn analysis into a small set of real strategic problems and plausible choices rather than a long catalog of observations.", "children": [{"id": "585eb866-5400-400a-b3f4-a0977cf81b70", "type": "subtopic", "title": "SWOT done well", "children": [{"id": "808364d5-4185-4f2e-82e8-ae311aef294e", "type": "concept", "title": "Strengths and weaknesses grounded in internal analysis"}, {"id": "8b4dd07f-d7ab-4b27-bf7f-2ac328689c1b", "type": "concept", "title": "Opportunities and threats grounded in external analysis"}, {"id": "d79ecb10-e4e7-4626-b9b6-a957c3fb96a3", "type": "concept", "title": "SO, ST, WO, and WT strategic implications"}], "description": "Students learn to make SWOT useful by tying it to evidence and decisions."}, {"id": "5438cb57-dcd3-453c-bb38-b7dc79155719", "type": "subtopic", "title": "Strategic issue diagnosis", "children": [{"id": "6c17adc6-5163-4ab8-bf54-42472340fe61", "type": "concept", "title": "Root causes versus symptoms"}, {"id": "1a82e992-1c98-4cb9-87bf-cba0bf5ec5b0", "type": "concept", "title": "Problem statements and decision questions"}, {"id": "a5aca09e-fe88-44bf-aad1-1e843fc36ad4", "type": "concept", "title": "Strategic tension and constraints"}], "description": "The goal is to name the few problems that matter most."}, {"id": "db0d6066-0f19-4e03-bb02-40e2fa577c69", "type": "subtopic", "title": "Generating options", "children": [{"id": "dd71cddf-45fc-45bb-9223-05cc2b6c2d69", "type": "concept", "title": "Mutually exclusive strategic options"}, {"id": "2835bbf7-90c5-4d96-b778-77ed2a0b1070", "type": "concept", "title": "No-regret moves, bets, and hedges"}, {"id": "945f417e-1383-48ae-84f6-55f9b7857be1", "type": "concept", "title": "Feasibility, attractiveness, and risk screens"}], "description": "Students learn to design alternatives before jumping to a favorite answer."}]}, {"id": "b65f8e25-d933-4011-af59-39507f753c08", "type": "topic", "title": "Corporate Strategy, Scope, Diversification, and Vertical Integration", "description": "This section asks which businesses belong together, where the firm should expand, and when ownership beats markets, alliances, or contracts.", "children": [{"id": "bdab08a7-311e-4b7c-a73f-6d1d66362ee7", "type": "subtopic", "title": "Scope of the firm", "children": [{"id": "9b8e0449-8acf-456d-adf6-e11cefeb2144", "type": "concept", "title": "Horizontal scope"}, {"id": "2eb51446-8e91-4ed4-8134-cfd764b89df0", "type": "concept", "title": "Vertical scope"}, {"id": "1288b545-5902-4fd4-97a6-ee7644d78d35", "type": "concept", "title": "Geographic and product-market scope"}], "description": "Students ask what businesses and activities the firm should own."}, {"id": "54d9a235-96e3-40fa-a66d-02a423b59b61", "type": "subtopic", "title": "Diversification logic", "children": [{"id": "35cd7418-b849-4aac-a0d6-838736b7c656", "type": "concept", "title": "Related and unrelated diversification"}, {"id": "63e12c94-1b2e-4087-8d53-778177da3741", "type": "concept", "title": "Economies of scope and parenting advantage"}, {"id": "ea530adb-2014-4d69-8209-3223e9f5222c", "type": "concept", "title": "Portfolio logic and the BCG matrix"}], "description": "Diversification should create corporate advantage, not just size."}, {"id": "b9036c3f-d42f-4c60-a3a0-43a0211aef08", "type": "subtopic", "title": "Vertical integration", "children": [{"id": "f25ba644-b359-4441-bf09-8e81890ea306", "type": "concept", "title": "Transaction costs and hold-up"}, {"id": "7012da79-e43a-470f-82af-6f437c9dfd1a", "type": "concept", "title": "Make, buy, partner, or platform decisions"}, {"id": "7aeb62de-494b-45b9-af08-b0a266582951", "type": "concept", "title": "Forward and backward integration"}], "description": "Students learn when integration improves coordination and when it creates rigidity."}]}, {"id": "9207e5f9-d176-4448-817a-191a956d9943", "type": "topic", "title": "Growth Strategy, M&A, Alliances, and Ecosystems", "description": "Students learn the strategic logic and failure modes of acquisitions, partnerships, ecosystems, joint ventures, and organic growth.", "children": [{"id": "8bb18e42-60f6-4590-8a9b-3b13fb9bf08d", "type": "subtopic", "title": "Organic growth", "children": [{"id": "e84e2db3-9097-4554-bb35-5c9e178749b4", "type": "concept", "title": "Market penetration, market development, product development"}, {"id": "bd1825db-ba9d-4301-b185-627d8c0794cc", "type": "concept", "title": "Adjacency moves and repeatable growth formulas"}, {"id": "720af5df-a2a3-461e-9f2a-0629671fc6c3", "type": "concept", "title": "Capability extension and resource constraints"}], "description": "Students learn how firms scale from the core into adjacencies."}, {"id": "7ddb2d66-9c24-4f3c-89f9-c0677c549816", "type": "subtopic", "title": "Mergers and acquisitions", "children": [{"id": "b0c57744-0711-4b3c-8dc4-400f3cf8ed2e", "type": "concept", "title": "Deal rationale and synergy types"}, {"id": "e631310d-82df-4f6b-bb91-75fe524efcf7", "type": "concept", "title": "Valuation, premiums, and integration risk"}, {"id": "2449a16b-b22d-46c9-81d6-649c59a67018", "type": "concept", "title": "Post-merger integration and culture fit"}], "description": "M&A is a strategy tool with severe execution risks."}, {"id": "b78dfdc6-93d8-4e13-8e2a-0bc928286ba3", "type": "subtopic", "title": "Alliances and ecosystems", "children": [{"id": "75936712-ffe9-4c17-aca0-4c4409c9b2b2", "type": "concept", "title": "Joint ventures, licensing, strategic alliances, and consortia"}, {"id": "7591113b-9773-43ea-8d8b-0a4752495a5d", "type": "concept", "title": "Partner selection and governance"}, {"id": "4b3ce641-f8b3-4198-9400-f125062468df", "type": "concept", "title": "Ecosystem orchestration and complementors"}], "description": "Partnerships let firms access capabilities without full ownership."}]}, {"id": "a18c7b4b-cb06-41ef-ac0e-8f305e851edb", "type": "topic", "title": "Global and Nonmarket Strategy", "description": "This topic connects international expansion with institutional differences, regulation, geopolitics, localization, and stakeholder influence.", "children": [{"id": "e0abf43a-cb61-43b5-87f5-c5a018ea2ee8", "type": "subtopic", "title": "International expansion", "children": [{"id": "af748d99-6e4c-4677-9cc5-b43a48fb4271", "type": "concept", "title": "CAGE distance and institutional differences"}, {"id": "755af3b5-ca63-4ba5-a71c-f09edc1d5e57", "type": "concept", "title": "Global, multidomestic, transnational, and international strategies"}, {"id": "3710d996-934c-4483-b058-ba7ac2e4cf9e", "type": "concept", "title": "Entry modes and localization"}], "description": "Students learn how global strategy balances scale, adaptation, and arbitrage."}, {"id": "24f94b18-cf49-4843-82d5-378d1d7aa11d", "type": "subtopic", "title": "Nonmarket strategy", "children": [{"id": "1597a636-22a7-4a9f-81a5-60a28dd63b4f", "type": "concept", "title": "Regulatory strategy and lobbying"}, {"id": "d7b33a04-ebb0-4fff-bf5e-2cca8b566965", "type": "concept", "title": "Standards, certifications, and public affairs"}, {"id": "bae2f243-5740-40da-a219-4d12ced9e5fe", "type": "concept", "title": "Geopolitical risk and sanctions"}], "description": "Firms compete through regulation, standards, legitimacy, and public policy as well as markets."}, {"id": "cb2ee1a8-8000-4aec-a39b-e5d5228aad4d", "type": "subtopic", "title": "Stakeholder context across markets", "children": [{"id": "ec277491-5e62-49f3-8ba1-c0775ecf86b4", "type": "concept", "title": "Labor, communities, NGOs, governments, and media"}, {"id": "1c668ee6-c67a-4d7a-91f2-64132f23ac28", "type": "concept", "title": "Cultural intelligence and ethical adaptation"}, {"id": "88652c26-3bea-4338-99c3-a290cbebc919", "type": "concept", "title": "Reputation and legitimacy"}], "description": "Strategy must fit local institutions and social expectations."}]}, {"id": "23dc757c-3301-40a8-a906-5cf5a6f2ce84", "type": "topic", "title": "Innovation, Disruption, Platforms, and Digital Strategy", "description": "Students examine how technology, platforms, network effects, and disruption reshape advantage and expose incumbents to strategic renewal problems.", "children": [{"id": "45bc83ee-48de-4c07-bb89-434b7e362275", "type": "subtopic", "title": "Innovation strategy", "children": [{"id": "c221b7f2-09bc-4a64-bd51-8ffc697b9318", "type": "concept", "title": "Sustaining and disruptive innovation"}, {"id": "1e9c925a-40e0-4b57-85fe-cb63c38f7c18", "type": "concept", "title": "Innovation portfolios and stage gates"}, {"id": "38e310ce-565c-4ed2-acde-d66453838b18", "type": "concept", "title": "Open innovation and corporate venturing"}], "description": "Students learn how firms choose innovation domains and manage exploration versus exploitation."}, {"id": "a158e73b-b20a-4fc3-99cf-0636228d4daa", "type": "subtopic", "title": "Platform strategy", "children": [{"id": "76e7b9e2-2c28-4e76-9655-b8553a53e0b4", "type": "concept", "title": "Network effects and chicken-and-egg problems"}, {"id": "5fe1fb2e-532b-4820-8987-d3ef40299492", "type": "concept", "title": "Governance, pricing, and trust"}, {"id": "b130ec12-3cf7-47fd-94df-039d3b68080c", "type": "concept", "title": "Standards, interoperability, and ecosystem health"}], "description": "Platforms compete by coordinating users, complements, and rules."}, {"id": "9c7fe9fb-7bae-4ccf-87cc-3a8fa557578d", "type": "subtopic", "title": "Digital and AI-era strategy", "children": [{"id": "34738980-6909-4dd7-80e1-c136369ebbfe", "type": "concept", "title": "Data-driven advantage"}, {"id": "c6dba096-6ca6-42dd-8703-3d152bafea1b", "type": "concept", "title": "AI-enabled scale and automation"}, {"id": "2ee3601b-8f24-4c7f-9b62-5780f8935028", "type": "concept", "title": "Digital transformation and incumbent renewal"}], "description": "Technology changes cost structures, data advantages, and operating models."}]}, {"id": "c964a4db-0b3d-4fec-ab31-bcb36d0b47b5", "type": "topic", "title": "Competitive Dynamics, Game Theory, and Strategic Commitment", "description": "This topic teaches students to anticipate rival behavior, make credible commitments, and choose moves in interdependent markets.", "children": [{"id": "d7848a29-3840-4107-bb52-a707de5241fb", "type": "subtopic", "title": "Rivalry and response", "children": [{"id": "d39208a5-a3f9-45f4-898e-e788f351c746", "type": "concept", "title": "Competitor intelligence"}, {"id": "63d41810-7162-4298-84c0-22d5e9d2bdc5", "type": "concept", "title": "Attack, retaliation, accommodation, and deterrence"}, {"id": "c6b1f4a5-a17d-4a72-a710-b3e5ffce25fa", "type": "concept", "title": "Signals, bluffs, and strategic transparency"}], "description": "Students learn to anticipate rather than merely react."}, {"id": "5024bc86-b1ed-4317-b54b-ed51367aed36", "type": "subtopic", "title": "Game theory for managers", "children": [{"id": "4ba8c11d-dfad-4d41-bff4-b8a494bcbfda", "type": "concept", "title": "Payoffs, dominant strategies, Nash equilibrium"}, {"id": "863c299a-ccf4-4a87-9420-699c034fe607", "type": "concept", "title": "Sequential games and backward induction"}, {"id": "27c62b22-a488-43cb-913d-25530a2416d8", "type": "concept", "title": "Repeated games and cooperation"}], "description": "Game theory gives language for interdependent choices."}, {"id": "4eb9bb66-6706-4dad-aa25-2d2dac09afa5", "type": "subtopic", "title": "Strategic commitment", "children": [{"id": "14f00d44-e562-478d-834d-38791c72a6be", "type": "concept", "title": "Capacity commitments and entry deterrence"}, {"id": "18a4af9c-4e0c-4148-9291-f53ba2003c92", "type": "concept", "title": "Preemption, lock-in, and credible threats"}, {"id": "b253abbd-9a43-4b93-abd5-805c52e4de7b", "type": "concept", "title": "Irreversibility and option value"}], "description": "Commitments shape rival expectations and market outcomes."}]}, {"id": "d0b1811b-44b7-4bcd-8ac2-f2f39e0b32b9", "type": "topic", "title": "Strategy Under Uncertainty, Scenarios, and Real Options", "description": "Students learn how to make strategic choices when forecasts are fragile, information is incomplete, and the future contains multiple plausible paths.", "children": [{"id": "fc456c69-0604-4379-9c59-18855104db7b", "type": "subtopic", "title": "Types of uncertainty", "children": [{"id": "de949a5e-75d3-45c2-93e5-62bb3eb387f5", "type": "concept", "title": "Known risks, known unknowns, and unknown unknowns"}, {"id": "128e7911-e1d0-41d8-a503-a5ac54527505", "type": "concept", "title": "Forecasting limits"}, {"id": "c9182240-383d-49fe-830d-532627b5eddf", "type": "concept", "title": "Sensitivity and stress testing"}], "description": "Students learn to separate risk that can be estimated from ambiguity that must be managed."}, {"id": "77a41265-7cc0-4003-bb7f-5388276550b3", "type": "subtopic", "title": "Scenario planning", "children": [{"id": "10b52b39-a4d2-4530-bb12-1a41e25c12ab", "type": "concept", "title": "Critical uncertainties"}, {"id": "16d7ac3b-07c3-4a7b-a120-629d4383ffbb", "type": "concept", "title": "Scenario narratives and signposts"}, {"id": "51f03aa1-58a7-49aa-a9d3-c7d5eb8fedcb", "type": "concept", "title": "Strategic implications across scenarios"}], "description": "Scenarios help decision makers rehearse multiple futures."}, {"id": "93af08d7-5479-46fe-9c39-8024609c31a8", "type": "subtopic", "title": "Real options and staged commitments", "children": [{"id": "ff7f933a-bbaa-4f1c-8c66-b1f37cca8ef0", "type": "concept", "title": "Experimentation and pilots"}, {"id": "e9837bfc-a3a8-42ad-bc1f-5500f3f8eaa9", "type": "concept", "title": "Stage gates and learning milestones"}, {"id": "1f81b872-1bd9-47eb-b3ac-71ef24f12982", "type": "concept", "title": "Scale-up, defer, abandon, and pivot choices"}], "description": "Students learn to preserve flexibility while still moving forward."}]}, {"id": "78dd235d-7723-4151-92fc-611680cd34f6", "type": "topic", "title": "Governance, Stakeholders, Sustainability, and Strategic Risk", "description": "World-class strategy includes governance, responsibility, risk, and legitimacy alongside shareholder value and competitive advantage.", "children": [{"id": "4673c0b9-c174-4cc3-a3f4-a9142afcf137", "type": "subtopic", "title": "Corporate governance", "children": [{"id": "8dca5910-2d1c-446b-8a04-7df198fb484b", "type": "concept", "title": "Boards, executives, owners, and fiduciary duties"}, {"id": "a0d1e506-a593-4534-8c0b-5603ef2b91ee", "type": "concept", "title": "Agency problems and incentives"}, {"id": "c92ea844-1e0e-4add-84f1-6cb39377faca", "type": "concept", "title": "Governance failures and oversight"}], "description": "Governance shapes who has authority and how leaders are held accountable."}, {"id": "77861ba5-5033-4307-9014-dfe597c71321", "type": "subtopic", "title": "Stakeholder strategy", "children": [{"id": "a1818d5b-dd9a-4fe8-ac13-3e1bbb6c08d5", "type": "concept", "title": "Stakeholder mapping and salience"}, {"id": "95cf43d6-e7a8-499f-981f-41f1e9a244bd", "type": "concept", "title": "Tradeoffs and shared value"}, {"id": "c6262b32-475d-4287-9832-bf5ffa932fff", "type": "concept", "title": "Trust, legitimacy, and social license"}], "description": "Students learn to treat stakeholders as part of strategic reality, not public-relations decoration."}, {"id": "ce9938d5-6d52-44a2-bed5-8097e33bf596", "type": "subtopic", "title": "Sustainability and risk", "children": [{"id": "b007e782-79cf-4483-972a-29fb70555e7c", "type": "concept", "title": "ESG and materiality"}, {"id": "a3c49124-6394-4460-a01f-7c382cddbe61", "type": "concept", "title": "Climate, supply-chain, and reputation risk"}, {"id": "4d9af980-887b-4dae-a11b-28aef15fa330", "type": "concept", "title": "Strategic risk registers and mitigation"}], "description": "Long-run advantage depends on resilience and responsible conduct."}]}, {"id": "b3a8426d-9d88-4eaa-add3-17e12348d2b1", "type": "topic", "title": "Strategy Implementation, Operating Model, and Resource Allocation", "description": "Students learn that strategy fails when choices do not translate into structure, budgets, processes, talent, incentives, and metrics.", "children": [{"id": "67ff7e43-1645-4feb-9805-2c37dc2d4a31", "type": "subtopic", "title": "Operating model design", "children": [{"id": "ee2b9a0f-48e1-4e75-b365-5a820c5c3000", "type": "concept", "title": "Organizational structure and decision rights"}, {"id": "67964160-d7f8-4f78-aede-688c4abcf8c7", "type": "concept", "title": "Processes, governance forums, and accountabilities"}, {"id": "3586fb43-6eca-45d9-9e38-931f601860cb", "type": "concept", "title": "Centralization, decentralization, and matrix tradeoffs"}], "description": "Strategy has to show up in structure and work systems."}, {"id": "4a664438-50e0-4949-a0b0-f48dec9afdce", "type": "subtopic", "title": "Resource allocation", "children": [{"id": "13a0a8e7-599b-4692-a122-94bb108b3d11", "type": "concept", "title": "Capital allocation and strategic priorities"}, {"id": "ba22b416-ee7a-4b14-a95e-cd35689dd4f1", "type": "concept", "title": "Zero-based and portfolio budgeting"}, {"id": "b72878c7-c060-46c4-b727-31abb7fc5e8e", "type": "concept", "title": "Talent allocation and capability investment"}], "description": "Budgets reveal true strategy."}, {"id": "c72a0ead-ae20-46d1-be57-4966b767ffef", "type": "subtopic", "title": "Implementation roadmap", "children": [{"id": "03b94b11-ebc8-47c8-8a49-20659b2af183", "type": "concept", "title": "Initiatives, milestones, owners, dependencies"}, {"id": "3d8987f7-4809-4089-9264-19447c4b1706", "type": "concept", "title": "Change risks and mitigation"}, {"id": "b4748edc-881d-4e18-b42d-776fdb0be6c7", "type": "concept", "title": "Benefits realization and review cadence"}], "description": "Students learn to convert recommendations into sequenced action."}]}, {"id": "d1005690-b960-468a-a835-8578790bb849", "type": "topic", "title": "Strategic Leadership, Culture, Change, and Communication", "description": "This topic focuses on the leadership work of aligning people, culture, narratives, coalitions, and behavior with strategic priorities.", "children": [{"id": "3123233d-e19b-494e-953a-18d9f0eba13e", "type": "subtopic", "title": "Leadership and strategic alignment", "children": [{"id": "f1698886-aab4-4e99-b54d-c51c6667b480", "type": "concept", "title": "Strategic narratives"}, {"id": "8c671358-48fa-4d02-ab5b-8924a9968db8", "type": "concept", "title": "Coalition building"}, {"id": "975414b0-8ee0-4e3f-9692-3829b0a1aa30", "type": "concept", "title": "Decision discipline and follow-through"}], "description": "Leaders turn strategy into shared direction and disciplined action."}, {"id": "e1c448e5-be86-4a7c-bd7e-29c3ab2927f8", "type": "subtopic", "title": "Culture and capabilities", "children": [{"id": "9eacceb9-dfce-4813-bb6a-0108d9fdc1db", "type": "concept", "title": "Norms, rituals, incentives, and stories"}, {"id": "43992628-e6a5-43a8-9f19-36008deac5fd", "type": "concept", "title": "Culture diagnostics"}, {"id": "b8f7eaef-25e0-43dd-992f-942176209490", "type": "concept", "title": "Capability-building programs"}], "description": "Culture can be a source of advantage or a barrier to change."}, {"id": "78e04819-532d-4985-9177-15578c922925", "type": "subtopic", "title": "Communicating strategy", "children": [{"id": "3d9c3436-c4a6-45c9-a231-7fc43a09f5d3", "type": "concept", "title": "Executive presentations"}, {"id": "381411be-4fa2-43c7-8a54-2109705788bb", "type": "concept", "title": "Board memos"}, {"id": "823e06ee-f7ab-4216-9e4e-42542ec0e59f", "type": "concept", "title": "Town halls, cascades, and manager toolkits"}], "description": "A strategy must be understandable enough to guide choices at every level."}]}, {"id": "8aee7ac7-24c2-4d1e-b5c8-88ba2dd263f9", "type": "topic", "title": "Strategy Metrics, Performance Management, and Strategic Control", "description": "Students learn how to measure strategy without confusing dashboards for judgment or short-term metrics for durable advantage.", "children": [{"id": "d3deb977-6b60-47a9-b28a-4ab6a40fa9c0", "type": "subtopic", "title": "Strategic metrics", "children": [{"id": "134eb708-632f-4a92-9e5b-ee247e80e3cc", "type": "concept", "title": "Financial, customer, process, learning, and ESG metrics"}, {"id": "64222aae-f87f-4390-b2dd-c2499efc147e", "type": "concept", "title": "Leading versus lagging indicators"}, {"id": "fcae6f77-e945-4251-b9d3-922e2deef5d0", "type": "concept", "title": "Metric integrity and gaming risks"}], "description": "Students learn to choose measures that track progress toward advantage."}, {"id": "94978641-4f82-44de-81d7-0bec66289e0b", "type": "subtopic", "title": "Balanced scorecards and OKRs", "children": [{"id": "f0fd6f34-0a2f-4208-b5fa-cd8b83166404", "type": "concept", "title": "Objectives, key results, and initiatives"}, {"id": "d203b647-07eb-4c58-89a2-20c585194517", "type": "concept", "title": "Strategy maps"}, {"id": "3a7d81b7-dc1a-4e02-a593-7faed21eb9a3", "type": "concept", "title": "Targets, owners, and review rhythms"}], "description": "Performance systems help translate strategy into measurable commitments."}, {"id": "10ab83e9-793a-4433-8ca8-de7c4601822e", "type": "subtopic", "title": "Strategic control", "children": [{"id": "dc37aee6-0ec8-4bf0-a6b9-f48c504e36ef", "type": "concept", "title": "Assumption testing"}, {"id": "1acda140-ac44-4413-b9dd-032a16b25a19", "type": "concept", "title": "Variance analysis and strategic reviews"}, {"id": "9a5d8852-9d61-4b48-8dbf-fad5d420fc14", "type": "concept", "title": "Adaptation, escalation, and abandonment decisions"}], "description": "Control is the learning loop of strategy."}]}, {"id": "bc54b267-56c4-45a8-8de5-c74e796dc114", "type": "topic", "title": "Integrated Strategy Capstone and Board-Ready Recommendation", "description": "The course culminates in a professional strategy recommendation built from evidence, alternatives, financial logic, implementation planning, and risk analysis.", "children": [{"id": "c50a9ed2-0a57-46c1-b520-64c7c30ed66a", "type": "subtopic", "title": "Case diagnosis", "children": [{"id": "8d772d44-b0e2-4b11-8c0f-670fe42bfc82", "type": "concept", "title": "Company, industry, customer, competitor, and financial evidence"}, {"id": "206645f9-326a-441d-b84c-3a0b8f1c9ad5", "type": "concept", "title": "Issue tree and hypothesis-driven analysis"}, {"id": "514ec2bb-2960-47b2-95dd-15e9e8873a1a", "type": "concept", "title": "Root cause and decision question"}], "description": "Students synthesize evidence into a crisp strategic problem."}, {"id": "2b2b5eca-2e60-49cd-ac42-f0d6720d0be9", "type": "subtopic", "title": "Recommendation design", "children": [{"id": "67b8fd0a-b6c3-4151-92b2-c6b646055071", "type": "concept", "title": "Strategic options and evaluation criteria"}, {"id": "6a895399-7b5a-4411-8403-2db99eccb91d", "type": "concept", "title": "Economics, risks, implementation, and stakeholder effects"}, {"id": "6657fd0c-a976-468a-8c8b-cc8f06a6791f", "type": "concept", "title": "Sensitivity and scenario analysis"}], "description": "A strong recommendation compares real alternatives and explains why one wins."}, {"id": "684fd860-e4ed-497a-bd81-f915659d43d9", "type": "subtopic", "title": "Board-ready deliverable", "children": [{"id": "9f78178e-625a-4f2d-815b-9ca8fa107a32", "type": "concept", "title": "Executive memo and slide deck"}, {"id": "1af730fd-fe03-4e2e-ac10-7e67e8dbe8c1", "type": "concept", "title": "Implementation roadmap and metrics"}, {"id": "853ce907-d810-4b09-8a06-de292ac39154", "type": "concept", "title": "Risks, next steps, and decision asks"}], "description": "The final product should be usable by executives, investors, or a client team."}]}], "dbBacked": true}$stmgjson$::jsonb,
